SELECT required_lesson_count
FROM biz_exemption_standard
WHERE academic_year = #{academicYear}
  AND semester = #{semester}
  AND grade = #{grade}
LIMIT 1

SELECT COUNT(*)
FROM biz_exemption_application
WHERE dept_id = #{deptId}
  AND teacher_id = #{teacherId}
  AND academic_year = #{academicYear}
  AND semester = #{semester}
  AND grade = #{grade}

SELECT 
FROM biz_exemption_application application
WHERE application.teacher_id = #{teacherId}
  AND application.dept_id = #{deptId}
ORDER BY application.submit_time DESC, application.application_id DESC

SELECT , GROUP_CONCAT( CONCAT(class_snapshot.class_code, '班 ', class_snapshot.used_lesson_count, '/', class_snapshot.required_lesson_count, ' ', class_snapshot.usage_rate, '%') ORDER BY CAST(class_snapshot.class_code AS UNSIGNED), class_snapshot.class_code SEPARATOR '；' ) AS classUsageSummary FROM biz_exemption_application application LEFT JOIN biz_exemption_class_snapshot class_snapshot ON class_snapshot.application_id = application.application_id
application.academic_year = #{q.academicYear}
AND application.semester = #{q.semester}
AND application.grade = #{q.grade}
AND application.status = #{q.status}
AND application.dept_id = #{q.deptId}
AND (application.teacher_name_snapshot LIKE CONCAT('%', #{q.keyword}, '%') OR application.dept_name_snapshot LIKE CONCAT('%', #{q.keyword}, '%'))
GROUP BY application.application_id ORDER BY application.submit_time DESC, application.application_id DESC

SELECT 
FROM biz_exemption_application application
WHERE application.application_id = #{applicationId}
